            <?php if ($sheet['rows'] === [] || $sheet['columns'] === []): ?><p class="p-5 text-xs text-slate-400">Esta hoja no tiene celdas visibles para diligenciar.</p><?php else: ?><div class="library-grid-wrap"><table class="library-grid"><thead><tr><th class="library-row-number"></th><?php foreach ($sheet['columns'] as $column): ?><th><?= e(\App\Services\SgsstLibrary::columnName($column)) ?></th><?php endforeach; ?></tr></thead><tbody>
                <?php foreach ($sheet['rows'] as $row): ?><tr><th class="library-row-number"><?= $row ?></th><?php foreach ($sheet['columns'] as $column): $coordinate = \App\Services\SgsstLibrary::columnName($column) . $row; if (isset($sheet['merged'][$coordinate])) continue; $cell = $sheet['cells'][$coordinate] ?? []; $formula = $cell['f'] ?? null; $hasResponseValue = isset($values[$sheetName]) && array_key_exists($coordinate, $values[$sheetName]); $value = $formula ? ($calculated[$sheetName][$coordinate] ?? $values[$sheetName][$coordinate] ?? $cell['v'] ?? '') : ($hasResponseValue ? $values[$sheetName][$coordinate] : ($cell['v'] ?? '')); $value = is_bool($value) ? ($value ? 'TRUE' : 'FALSE') : (string) $value; $editable = !$formula && ($value === '' || !empty($cell['s']['unlocked'])); $classes = ['library-cell']; if (!empty($cell['s']['b'])) $classes[] = 'font-bold'; if (!empty($cell['s']['i'])) $classes[] = 'italic'; if (!empty($cell['s']['border'])) $classes[] = 'library-bordered'; $style = ''; if (!empty($cell['s']['fill']) && preg_match('/^[A-F0-9]{6}$/i', $cell['s']['fill'])) $style .= 'background:#' . $cell['s']['fill'] . ';'; if (in_array($cell['s']['align'] ?? '', ['left', 'center', 'right', 'justify'], true)) $style .= 'text-align:' . $cell['s']['align'] . ';'; $unsupportedKey = $sheetName . '!' . $coordinate; ?>
                    <td<?= !empty($cell['colspan']) ? ' colspan="' . min(50, (int) $cell['colspan']) . '"' : '' ?><?= !empty($cell['rowspan']) ? ' rowspan="' . min(500, (int) $cell['rowspan']) . '"' : '' ?>><?php if ($formula): ?><div class="library-cell library-formula<?= isset($unsupported[$unsupportedKey]) ? ' library-unsupported' : '' ?>" data-formula-cell title="=<?= e($formula) ?>"<?= $style ? ' style="' . e($style) . '"' : '' ?>><?= e($value) ?></div><?php elseif (isset($cell['options'])): ?><select class="library-cell library-select" data-cell data-sheet="<?= e($sheetName) ?>" data-coordinate="<?= e($coordinate) ?>" style="<?= e($style) ?>"><?php $options = $cell['options']; if ($value !== '' && !in_array($value, $options, true)) array_unshift($options, $value); ?><option value=""></option><?php foreach ($options as $option): ?><option value="<?= e($option) ?>"<?= selected($value, (string) $option) ?>><?= e($option) ?></option><?php endforeach; ?></select><?php else: ?><div class="<?= e(implode(' ', $classes)) ?>" data-cell data-sheet="<?= e($sheetName) ?>" data-coordinate="<?= e($coordinate) ?>" contenteditable="<?= $editable ? 'true' : 'false' ?>" data-editable-default="<?= $editable ? '1' : '0' ?>" role="textbox"<?= $style ? ' style="' . e($style) . '"' : '' ?>><?= e($value) ?></div><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?>
            </tbody></table></div><?php endif; ?>
        </section>
    <?php endforeach; ?>
    <div class="sticky bottom-4 z-10 mt-5 flex justify-end"><button type="submit" class="btn-primary shadow-lg" data-library-submit disabled>Guardar registro</button></div>
</form>
